      "inset 0 -2px 3px rgb(52 116 157 / 0.25), inset 0 0 0 1px rgb(255 255 255 / 0.6), 0 0 0 1.5px #7ab9e1, 0 2px 3px rgb(43 101 137 / 0.3)",
