      "radial-gradient(120% 160% at 50% 25%, #effff3 0%, #7af5a3 35%, #22c25c 100%)",
    boxShadow:
      "inset 0 -2px 3px rgb(0 90 40 / 0.35), 0 0 0 1.5px #3bd477, 0 0 10px rgb(80 255 140 / 0.95), 0 0 26px rgb(60 240 120 / 0.55), 0 2px 3px rgb(0 80 40 / 0.3)",
  },
  red: {
    background:
      "radial-gradient(120% 160% at 50% 25%, #fff0f1 0%, #ff7c88 35%, #e0283b 100%)",
    boxShadow:
      "inset 0 -2px 3px rgb(120 0 20 / 0.35), 0 0 0 1.5px #ff5466, 0 0 10px rgb(255 80 100 / 0.95), 0 0 26px rgb(255 60 80 / 0.55), 0 2px 3px rgb(120 0 20 / 0.3)",
  },
