const COIN_STYLE: Record<
  number,
  { face: string; rim: string; ink: string; edge: string; hi: string }
> = {
  100: {
    face: "radial-gradient(circle at 35% 28%, #ffffff 0%, #e6e8ec 30%, #c3c7cf 70%, #a3a8b2 100%)",
    rim: "#9ca1ab",
    ink: "#8b9099",
    hi: "#ffffff",
    edge: "repeating-linear-gradient(180deg, #d7dae0 0 1.5px, #8a8f99 1.5px 3px)",
  },
  10: {
    face: "radial-gradient(circle at 35% 28%, #ffe3c4 0%, #e3a46e 38%, #b87136 75%, #94572a 100%)",
    rim: "#8f5428",
    ink: "#7a4519",
    hi: "#ffd9b5",
    edge: "linear-gradient(90deg, #8c5124, #d29560 50%, #8c5124)",
  },
};

/** A coin with real thickness: a front face, a back face and an edge, so turning it 90° shows the edge. */
function Coin({
  value,
  angle = 0,
  smooth = true,
  lifted = false,
}: {
  value: number;
  angle?: number;
  smooth?: boolean;
  lifted?: boolean;
}) {
  const s = COIN_STYLE[value];
  const id = useId();
  const t = value === 100 ? 9 : 7; // thickness, units
  const face = (back: boolean): CSSProperties => ({
    background: value === 10 ? undefined : s.face,
    transform: `${back ? "rotateY(180deg) " : ""}translateZ(${u(t / 2)})`,
    boxShadow:
      value === 10
        ? undefined
        : `inset 0 0 0 ${u(2.5)} ${s.rim}, inset 0 0 0 ${u(4)} rgb(255 255 255 / 0.45), inset 0 ${u(-5)} ${u(9)} rgb(0 0 0 / 0.2), inset 0 ${u(4)} ${u(6)} rgb(255 255 255 / 0.5)`,
    backfaceVisibility: "hidden",
  });
  return (
    // The shadow lives out here: a filter on the 3D element itself would flatten it.
    <div
      className="size-full transition-[filter] duration-300"
      style={{
        perspective: u(500),
        filter: lifted
          ? `drop-shadow(0 ${u(16)} ${u(12)} rgb(34 86 118 / 0.35))`
          : `drop-shadow(0 ${u(4)} ${u(4)} rgb(34 86 118 / 0.3))`,
      }}
    >
      <div
        className="relative size-full"
        style={{
          transformStyle: "preserve-3d",
          transform: `rotateY(${angle}deg)`,
          transition: smooth
            ? "transform .5s cubic-bezier(.34,1.3,.64,1)"
            : "transform .08s linear",
        }}
      >
        {[false, true].map((back) => (
          <div
            key={String(back)}
            className="absolute inset-0 rounded-full"
            style={face(back)}
          >
            {value === 10 ? (
              <TenYen id={`${id}${back ? "b" : "f"}`} />
            ) : (
              <svg
                viewBox="0 0 100 100"
                className="absolute inset-0 size-full"
                aria-hidden
              >
                {/* milled dot ring */}
                <circle
                  cx="50"
                  cy="50"
                  r="40"
                  fill="none"
                  stroke={s.ink}
                  strokeOpacity=".55"
                  strokeWidth="1.6"
                  strokeDasharray="0.1 4.1"
                  strokeLinecap="round"
                />
                {value === 100 && <Sakura ink={s.ink} hi={s.hi} />}
                <text
                  x="50"
                  y={value === 100 ? 66 : 58}
                  textAnchor="middle"
                  fontFamily="var(--font-sans), system-ui"
                  fontWeight="700"
                  fontSize={value === 100 ? 22 : 26}
                  letterSpacing="-1"
                  fill={s.ink}
                  stroke={s.hi}
                  strokeOpacity=".7"
                  strokeWidth=".6"
                  paintOrder="stroke"
                >
                  {value}
                </text>
              </svg>
            )}
          </div>
        ))}
        {/* edge */}
        <div
          className="absolute top-0 left-1/2 h-full rounded-full"
          style={{
            width: u(t),
            marginLeft: u(-t / 2),
            background: s.edge,
            transform: "rotateY(90deg)",
            boxShadow: `inset ${u(2)} 0 ${u(2)} rgb(255 255 255 / 0.5), inset ${u(-2)} 0 ${u(2)} rgb(0 0 0 / 0.3)`,
          }}
        />
      </div>
    </div>
  );
}

/** The ¥10 coin's value side: bronze with a raised rim, a satin field, tarnish, evergreen branches and the 10 in relief. */
function TenYen({ id }: { id: string }) {
  const R = 33.5;
  const branch = (side: number) => {
    const pts: [number, number, number][] = [];
    for (let i = 0; i <= 7; i++) {
      const deg = 90 + side * (12 + (i / 7) * 86); // from the bottom up to the side
      const a = (deg * Math.PI) / 180;
      pts.push([50 + R * Math.cos(a), 50 + R * Math.sin(a), deg]);
    }
    return pts;
  };
  const metal = { dark: "#6b3a17", mid: "#a2612c", light: "#ffd9b0" };
  return (
    <svg
      viewBox="0 0 100 100"
      className="absolute inset-0 size-full"
      aria-hidden
    >
      <defs>
        <radialGradient id={`${id}f`} cx="36%" cy="30%" r="78%">
          <stop offset="0" stopColor="#f6c08e" />
          <stop offset=".35" stopColor="#d48d52" />
          <stop offset=".75" stopColor="#ad6a33" />
          <stop offset="1" stopColor="#8a4f22" />
        </radialGradient>
        <linearGradient id={`${id}r`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#ffdcb6" />
          <stop offset=".45" stopColor="#c27b41" />
          <stop offset="1" stopColor="#6e3b17" />
        </linearGradient>
        <linearGradient id={`${id}t`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#e9a46a" />
          <stop offset="1" stopColor="#8d5124" />
        </linearGradient>
        <filter id={`${id}g`}>
          <feTurbulence
            type="fractalNoise"
            baseFrequency="2.4"
            numOctaves="2"
            seed="7"
          />
          <feColorMatrix values="0 0 0 0 .3  0 0 0 0 .16  0 0 0 0 .06  0 0 0 .4 0" />
          <feComposite operator="in" in2="SourceGraphic" />
        </filter>
        <filter id={`${id}b`}>
          <feGaussianBlur stdDeviation="3.5" />
        </filter>
        <clipPath id={`${id}c`}>
          <circle cx="50" cy="50" r="43" />
        </clipPath>
      </defs>

      {/* raised rim, then the field sunk inside it */}
      <circle cx="50" cy="50" r="49.5" fill={`url(#${id}r)`} />
      <circle cx="50" cy="50" r="43.5" fill={`url(#${id}f)`} />
      <g clipPath={`url(#${id}c)`}>
        <circle cx="50" cy="50" r="43" fill="#000" filter={`url(#${id}g)`} />
        {/* tarnish */}
        <ellipse
          cx="72"
          cy="70"
          rx="16"
          ry="10"
          fill="#4a2810"
          opacity=".22"
          filter={`url(#${id}b)`}
        />
        <ellipse
          cx="24"
          cy="62"
          rx="9"
          ry="13"
          fill="#4a2810"
          opacity=".16"
          filter={`url(#${id}b)`}
        />
        <ellipse
          cx="60"
          cy="18"
          rx="8"
          ry="5"
          fill="#3d200c"
          opacity=".14"
          filter={`url(#${id}b)`}
        />
        {/* sheen */}
        <ellipse
          cx="34"
          cy="28"
          rx="20"
          ry="9"
          transform="rotate(-35 34 28)"
          fill="#fff"
          opacity=".28"
          filter={`url(#${id}b)`}
        />
      </g>
      <circle
        cx="50"
        cy="50"
        r="43.5"
        fill="none"
        stroke="#5a3012"
        strokeOpacity=".45"
        strokeWidth="1.2"
      />
      <circle
        cx="50"
        cy="50"
        r="48.8"
        fill="none"
        stroke="#fff3e4"
        strokeOpacity=".5"
        strokeWidth=".8"
      />

      {/* evergreen branches */}
      {[-1, 1].map((side) => {
        const pts = branch(side);
        return (
          <g key={side}>
            <polyline
              points={pts.map(([x, y]) => `${x},${y + 0.6}`).join(" ")}
              fill="none"
              stroke={metal.light}
              strokeOpacity=".5"
              strokeWidth="1"
            />
            <polyline
              points={pts.map(([x, y]) => `${x},${y}`).join(" ")}
              fill="none"
              stroke={metal.dark}
              strokeOpacity=".8"
              strokeWidth=".9"
            />
            {pts.slice(1).map(([x, y, deg], i) => {
              const out = i % 2 ? 1 : -1;
              const rad = (deg * Math.PI) / 180;
              const cx = x + out * 3 * Math.cos(rad);
              const cy = y + out * 3 * Math.sin(rad);
              const size = 1 - i * 0.07;
              return (
                <ellipse
                  key={i}
                  cx={cx}
                  cy={cy}
                  rx={4.4 * size}
                  ry={1.8 * size}
                  transform={`rotate(${deg + 90 * side + out * 28 * side} ${cx} ${cy})`}
                  fill={`url(#${id}t)`}
                  stroke={metal.dark}
                  strokeOpacity=".75"
                  strokeWidth=".55"
                />
              );
            })}
          </g>
        );
      })}
      <circle
        cx="50"
        cy="84.5"
        r="1.6"
        fill={metal.mid}
        stroke={metal.dark}
        strokeWidth=".5"
      />

      {/* 日本国 and the 10, struck in relief: highlight above, shadow below */}
      {[
        { dy: -0.6, fill: metal.light, opacity: 0.75 },
        { dy: 0.8, fill: "#4a2508", opacity: 0.55 },
        { dy: 0, fill: `url(#${id}t)`, opacity: 1 },
      ].map(({ dy, fill, opacity }, i) => (
        <g
          key={i}
          fill={fill}
          opacity={opacity}
          fontFamily="var(--font-sans), system-ui"
          textAnchor="middle"
        >
          <text
            x="50"
            y={29 + dy}
            fontSize="8.5"
            fontWeight="700"
            letterSpacing="1.6"
          >
            日本国
          </text>
          <text
            x="50"
            y={62 + dy}
            fontSize="31"
            fontWeight="800"
            letterSpacing="-1.5"
          >
            10
          </text>
        </g>
      ))}
    </svg>
  );
}

/** The cherry blossom on the ¥100 coin, in low relief. */
function Sakura({ ink, hi }: { ink: string; hi: string }) {
  const petals = [0, 72, 144, 216, 288];
  const flower = (dx: number, dy: number, sc: number) => (
    <g transform={`translate(${dx} ${dy}) scale(${sc})`}>
      {petals.map((r) => (
        <path
          key={r}
          transform={`rotate(${r})`}
          d="M0 0 C -5 -4 -5 -11 -2 -13 L 0 -11 L 2 -13 C 5 -11 5 -4 0 0 Z"
          fill={hi}
          fillOpacity=".55"
          stroke={ink}
          strokeOpacity=".7"
          strokeWidth=".9"
        />
      ))}
      <circle r="1.6" fill={ink} fillOpacity=".7" />
    </g>
  );
  return (
    <>
      {flower(50, 34, 1)}
      {flower(31, 40, 0.62)}
      {flower(69, 40, 0.62)}
    </>
  );
}

function TrayThing({
  item,
  taken,
  currency,
  onTake,
  register,
}: {
  item: TrayItem;
  taken: boolean;
  currency: string;
  onTake: () => void;
  register: (el: HTMLElement | null) => void;
}) {
  const b = item.spawn;
  const [w, h] = b.shape === "box" ? [b.w, b.h] : [b.r * 2, b.r * 2];
  return (
    // Positioned by the physics loop; the inner layer handles hover and the lift-out.
    <div
      ref={register}
      className="absolute top-0 left-0"
      style={{ width: u(w), height: u(h), transform: place(b) }}
    >
      <button
        type="button"
        onClick={onTake}
        aria-label={
          item.kind === "can"
            ? `Take the ${item.drink.name}`
            : item.value === 100
              ? `Take your ${currency}100 coin`
              : `Take your ${currency}${item.value} change`
        }
        className={cn(
          "relative size-full cursor-pointer rounded-[12px] transition-[translate,scale,opacity,filter] duration-300 ease-out focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white",
          taken &&
            "pointer-events-none -translate-y-[40%] scale-125 opacity-0 blur-[6px]",
        )}
      >
        {item.kind === "can" ? (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 rotate-90">
            <Can drink={item.drink} />
          </div>
        ) : (
          <Coin value={item.value} />
        )}
      </button>
    </div>
  );
}

/** Body centre + angle -> CSS transform for an element sized to the body. */
function place(b: Body) {
  const [hw, hh] = b.shape === "box" ? [b.w / 2, b.h / 2] : [b.r, b.r];
  return `translate(${u(b.x - hw)}, ${u(b.y - hh)}) rotate(${b.a}rad)`;
}

/* ---------------------------------------------------------------------------
 * Tray physics
 * ------------------------------------------------------------------------- */

/**
 * Tiny 2D physics for the pickup tray: gravity, bounces that lose energy, a can that tips onto
 * its side, coins that roll (spin follows travel), and collisions between everything.
 * Units are the machine's design units; the tray's inner box is 266 x 98.
 */

const TRAY = { floor: 90, left: 12, right: 254 };
const G = 2400;

type Base = {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  a: number;
  va: number;
};
type Body =
  | (Base & { shape: "box"; w: number; h: number })
  | (Base & { shape: "disc"; r: number });

const MASS = { box: 6, disc: 1 };

/** Half extents of the body's axis-aligned bounds at its current angle. */
function extents(b: Body): [number, number] {
  if (b.shape === "disc") return [b.r, b.r];
  const c = Math.abs(Math.cos(b.a)),
    s = Math.abs(Math.sin(b.a));
  return [(b.w / 2) * c + (b.h / 2) * s, (b.w / 2) * s + (b.h / 2) * c];
}

/** Advance the world by dt seconds. `hit` fires on impacts with the impact speed. */
function step(
  bodies: Body[],
  dt: number,
  hit: (b: Body, speed: number) => void,
) {
  for (const b of bodies) {
    b.vy += G * dt;
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    b.a += b.va * dt;
  }

  for (let i = 0; i < bodies.length; i++)
    for (let j = i + 1; j < bodies.length; j++)
      collide(bodies[i], bodies[j], hit);

  for (const b of bodies) {
    const [ex, ey] = extents(b);
    let grounded = false;

    if (b.y + ey > TRAY.floor) {
      b.y = TRAY.floor - ey;
      grounded = true;
      if (b.vy > 0) {
        if (b.vy > 120) hit(b, b.vy);
        b.vy *= b.shape === "disc" ? -0.42 : -0.22;
        if (Math.abs(b.vy) < 60) b.vy = 0;
      }
    }
    if (b.x - ex < TRAY.left || b.x + ex > TRAY.right) {
      const left = b.x - ex < TRAY.left;
      b.x = left ? TRAY.left + ex : TRAY.right - ex;
      if (left ? b.vx < 0 : b.vx > 0) {
        if (Math.abs(b.vx) > 80) hit(b, Math.abs(b.vx) * 0.6);
        b.vx *= -0.5;
      }
    }

    if (!grounded) continue;
    const drag = (k: number) => Math.max(0, 1 - k * dt);
    if (b.shape === "disc") {
      b.va = b.vx / b.r; // rolling without slipping
      b.vx *= drag(0.9);
      if (Math.abs(b.vx) < 4) b.vx = 0;
    } else {
      // Gravity tips a box toward its long side (angle 0 or π); upright is the unstable balance.
      b.va += -Math.sin(2 * b.a) * 45 * dt;
      b.va *= drag(7);
      b.vx *= drag(6);
    }
  }
}

function collide(p: Body, q: Body, hit: (b: Body, speed: number) => void) {
  if (p.shape === "box" && q.shape === "disc") return collide(q, p, hit);

  let nx = 0,
    ny = 0,
    pen = 0;

  if (p.shape === "disc" && q.shape === "disc") {
    const dx = p.x - q.x,
      dy = p.y - q.y,
      d = Math.hypot(dx, dy);
    if (d >= p.r + q.r || d === 0) return;
    [nx, ny, pen] = [dx / d, dy / d, p.r + q.r - d];
  } else if (p.shape === "disc" && q.shape === "box") {
    // Closest point on the rotated box, in the box's frame.
    const c = Math.cos(q.a),
      s = Math.sin(q.a);
    const dx = p.x - q.x,
      dy = p.y - q.y;
    const lx = c * dx + s * dy,
      ly = -s * dx + c * dy;
    const ox = lx - Math.max(-q.w / 2, Math.min(q.w / 2, lx));
    const oy = ly - Math.max(-q.h / 2, Math.min(q.h / 2, ly));
    const d = Math.hypot(ox, oy);
    if (d >= p.r) return;
    const [lnx, lny] = d > 0 ? [ox / d, oy / d] : [0, -1];
    [nx, ny, pen] = [c * lnx - s * lny, s * lnx + c * lny, p.r - d];
  } else {
    // box vs box: axis-aligned bounds, pushed apart along the shallower axis
    const [aex, aey] = extents(p),
      [bex, bey] = extents(q);
    const dx = p.x - q.x,
      dy = p.y - q.y;
    const px = aex + bex - Math.abs(dx),
      py = aey + bey - Math.abs(dy);
    if (px <= 0 || py <= 0) return;
    if (px < py) [nx, ny, pen] = [Math.sign(dx) || 1, 0, px];
    else [nx, ny, pen] = [0, Math.sign(dy) || -1, py];
  }

  // n points from q to p. Split the push and the bounce by inverse mass.
  const ip = 1 / MASS[p.shape],
    iq = 1 / MASS[q.shape],
    sum = ip + iq;
  p.x += nx * pen * (ip / sum);
  p.y += ny * pen * (ip / sum);
  q.x -= nx * pen * (iq / sum);
  q.y -= ny * pen * (iq / sum);

  const vn = (p.vx - q.vx) * nx + (p.vy - q.vy) * ny;
  if (vn >= 0) return;
  const e = p.shape === "disc" ? 0.45 : 0.15;
  const j = (-(1 + e) * vn) / sum;
  p.vx += j * ip * nx;
  p.vy += j * ip * ny;
  q.vx -= j * iq * nx;
  q.vy -= j * iq * ny;
  if (-vn > 100) hit(p, -vn);
}

/* ---------------------------------------------------------------------------
 * Sound: tiny WebAudio synth, created on the first touch
 * ------------------------------------------------------------------------- */

let audio: AudioContext | null = null;
const ac = () => (audio ??= new AudioContext());

function tone(
  freq: number,
  dur: number,
  o: { type?: OscillatorType; gain?: number; at?: number; to?: number } = {},
) {
  const c = ac();
  const t = c.currentTime + (o.at ?? 0);
  const osc = c.createOscillator();
  const g = c.createGain();
  osc.type = o.type ?? "sine";
  osc.frequency.setValueAtTime(freq, t);
  if (o.to) osc.frequency.exponentialRampToValueAtTime(o.to, t + dur);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(o.gain ?? 0.15, t + 0.006);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  osc.connect(g).connect(c.destination);
  osc.start(t);
  osc.stop(t + dur + 0.02);
}

function noise(
  dur: number,
  o: {
    at?: number;
    gain?: number;
    freq?: number;
    type?: BiquadFilterType;
  } = {},
) {
  const c = ac();
  const t = c.currentTime + (o.at ?? 0);
  const buf = c.createBuffer(1, Math.ceil(c.sampleRate * dur), c.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  const src = c.createBufferSource();
  src.buffer = buf;
  const f = c.createBiquadFilter();
  f.type = o.type ?? "lowpass";
  f.frequency.value = o.freq ?? 800;
  const g = c.createGain();
  g.gain.setValueAtTime(o.gain ?? 0.3, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(f).connect(g).connect(c.destination);
  src.start(t);
}

/** A struck piece of metal: a few inharmonic partials, higher ones dying faster, plus a click. */
function metal(
  base: number,
  o: { at?: number; gain?: number; decay?: number } = {},
) {
  const gain = o.gain ?? 0.08;
  const decay = o.decay ?? 0.3;
  [1, 1.47, 2.09, 2.76].forEach((r, i) =>
    tone(base * r * (1 + (Math.random() - 0.5) * 0.01), decay / (1 + i * 0.6), {
      gain: gain / (1 + i * 0.9),
      at: o.at,
    }),
  );
  noise(0.012, { at: o.at, freq: 6000, type: "highpass", gain: gain * 2 });
}

const sfx = {
  unlock: () => void ac().resume(),
  clink: (vol = 1) =>
    metal(2900 + Math.random() * 500, { gain: 0.09 * vol, decay: 0.35 }),
  /** A coin ticking down a metal chute, the ticks spreading out as it slows. */
  chute: (at = 0) => {
    let t = at;
    for (let i = 0; i < 9; i++) {
      t += 0.026 + i * 0.006 + Math.random() * 0.01;
      noise(0.008, {
        at: t,
        freq: 4200 + Math.random() * 800,
        type: "bandpass",
        gain: 0.4 * (1 - i / 12),
      });
    }
    noise(0.35, { at, freq: 500, gain: 0.04 }); // low rumble of the chute
  },
  /** The coin mechanism: ka-chunk, then the chute. */
  kachak: () => {
    noise(0.02, { freq: 1800, type: "bandpass", gain: 0.9 });
    tone(190, 0.07, { gain: 0.12, to: 110 });
    noise(0.035, { at: 0.09, freq: 900, type: "bandpass", gain: 1.2 });
    tone(140, 0.1, { gain: 0.16, at: 0.09, to: 70 });
    sfx.chute(0.15);
  },
  insert: () => {
    metal(3300, { gain: 0.07, decay: 0.25 }); // the slot's lip
    setTimeout(sfx.kachak, 110);
    metal(1700, { at: 0.66, gain: 0.06, decay: 0.3 }); // lands in the cash box
    noise(0.05, { at: 0.66, freq: 700, gain: 0.15 });
  },
  nope: () => {
    tone(660, 0.09, { type: "square", gain: 0.03 });
    tone(520, 0.13, { type: "square", gain: 0.03, at: 0.11 });
  },
  pop: () => tone(600, 0.09, { gain: 0.07, to: 1150 }),
  lever: () => {
    noise(0.025, { freq: 3200, type: "bandpass", gain: 0.6 });
    tone(420, 0.05, { type: "square", gain: 0.03, to: 200 });
    noise(0.03, { at: 0.16, freq: 2400, type: "bandpass", gain: 0.5 });
  },
  flap: () => {
    noise(0.06, { freq: 900, type: "bandpass", gain: 0.5 });
    tone(140, 0.1, { gain: 0.08, to: 90 });
  },
  load: () => {
    tone(70, 0.75, { type: "triangle", gain: 0.12, to: 160 });
    noise(0.7, { freq: 300, gain: 0.06 });
    tone(880, 0.35, { gain: 0.08, at: 0.85 });
    tone(1320, 0.5, { gain: 0.07, at: 0.97 });
  },
  press: () => tone(1500, 0.05, { type: "square", gain: 0.035 }),
  thud: (vol = 1) => {
    noise(0.2, { freq: 420, gain: 0.55 * vol });
    tone(120, 0.28, { gain: 0.35 * vol, to: 48 });
  },
  error: () => {
    tone(920, 0.12, { type: "square", gain: 0.05 });
    tone(920, 0.12, { type: "square", gain: 0.05, at: 0.18 });
    tone(310, 0.4, { type: "square", gain: 0.05, at: 0.4 });
  },
  take: () => {
    noise(0.4, { freq: 3500, type: "highpass", gain: 0.12 }); // pssht
    tone(480, 0.14, { gain: 0.06, to: 980 });
  },
};

/** Break an amount into the coins the machine holds. */
function toCoins(amount: number) {
  const coins: number[] = [];
  for (const c of [100, 10]) {
    while (amount >= c) {
      coins.push(c);
      amount -= c;
    }
  }
  return coins;
}

const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
const dist = (a: { x: number; y: number }, b: { x: number; y: number }) =>
  Math.hypot(a.x - b.x, a.y - b.y);
